-- S2 rollback: never restore onto changed content or a newly claimed parent slug.
DO $orphan_revert$
DECLARE n integer;
BEGIN
 IF (SELECT count(*) FROM atlas_media_guard.orphan_event_media_backup) <> 19
 OR EXISTS (
 SELECT 1 FROM atlas_media_guard.orphan_event_media_backup b
 LEFT JOIN public.event_media m ON m.id=b.media_id
 WHERE m.id IS NULL OR m.status IS DISTINCT FROM 'hidden'
 OR md5((to_jsonb(m)-'status')::text) IS DISTINCT FROM b.content_md5
 OR EXISTS(SELECT 1 FROM public.events e WHERE e.slug=m.event_slug)) THEN
 RAISE EXCEPTION 'Quarantined rows changed or a slug acquired a parent: stop; no automatic restoration';
 END IF;
 UPDATE public.event_media m SET status=b.original_status
 FROM atlas_media_guard.orphan_event_media_backup b WHERE m.id=b.media_id;
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>19 THEN RAISE EXCEPTION 'Orphan restoration count mismatch'; END IF;
END;
$orphan_revert$;
